			// Lambda expression - if pixel is either not white and not fully transparent			bool isNonWhiteAndOpaquePixel(Color c) => !(c.R == 255 && c.G == 255 && c.B == 255) && c.A > 0;			// get min left non transparent pixel (scan Y collumn and shift right)			for (int x = 0; x < w; x++) {				for (int y = 0; y < h; y++) {					if (isNonWhiteAndOpaquePixel(bmp.GetPixel(x, y))) {						if (x < min.X) min.X = x; break;					}				}			}